  ai_model                            TEXT                ,                     -- FK -> AiModels.AiModelId.
  label                               TEXT                ,                     -- Human-readable label for this pricing era.
  currency                            TEXT                ,                     -- ISO currency code (lower-kebab), e.g. 'usd'.
  input_price_per_m_tok               NUMERIC             ,                     -- Price per 1,000,000 NON-cached input tokens.
  cached_input_price_per_m_tok        NUMERIC             ,                     -- Price per 1,000,000 cached input tokens (prompt-cache reads). 0 if unsupported.
  output_price_per_m_tok              NUMERIC             ,                     -- Price per 1,000,000 output (completion) tokens.
  effective_date                      DATE                ,                     -- Date this pricing took effect (date-only business date).
  is_active                           BOOLEAN             ,                     -- TRUE for the currently-billing version of this model; superseded versions are FALSE.
  notes                               TEXT                ,                     -- Free text — source/announcement of this pricing.
  created_at                          TIMESTAMPTZ         ,                     -- Audit: when this row was first inserted. Auto-stamped by the audit trigger (now() on INSERT); immutable thereafter.
  created_by                          TEXT                ,                     -- Audit: the OWNER — the JWT user (auth.email()) who created this row. Auto-stamped on INSERT; immutable thereafter. NULL for build-time seed rows (no signed-in user).
  modified_at                         TIMESTAMPTZ         ,                     -- Audit: when this row was last written. Auto-stamped by the audit trigger (now() on every INSERT/UPDATE).
  modified_by                         TEXT                ,                     -- Audit: the JWT user (auth.email()) who last wrote this row. Auto-stamped on every INSERT/UPDATE.
  modified_by_model                   TEXT                                      -- Audit: the AI model credited on the last save when an LLM made/assisted the change (e.g. "gpt-4o"). NULL for plain human writes. Read from the app.modified_by_model session GUC by the audit trigger. The owner (CreatedBy/ModifiedBy) is always the human JWT user, never a model.
);
COMMENT ON COLUMN model_pricing_versions.model_pricing_version_id IS 'Slug PK, e.g. ''gpt-4o-mini-2025-07''.';
COMMENT ON COLUMN model_pricing_versions.ai_model IS 'FK -> AiModels.AiModelId.';
COMMENT ON COLUMN model_pricing_versions.label IS 'Human-readable label for this pricing era.';
COMMENT ON COLUMN model_pricing_versions.currency IS 'ISO currency code (lower-kebab), e.g. ''usd''.';
COMMENT ON COLUMN model_pricing_versions.input_price_per_m_tok IS 'Price per 1,000,000 NON-cached input tokens.';
COMMENT ON COLUMN model_pricing_versions.cached_input_price_per_m_tok IS 'Price per 1,000,000 cached input tokens (prompt-cache reads). 0 if unsupported.';
COMMENT ON COLUMN model_pricing_versions.output_price_per_m_tok IS 'Price per 1,000,000 output (completion) tokens.';
COMMENT ON COLUMN model_pricing_versions.effective_date IS 'Date this pricing took effect (date-only business date).';
COMMENT ON COLUMN model_pricing_versions.is_active IS 'TRUE for the currently-billing version of this model; superseded versions are FALSE.';
COMMENT ON COLUMN model_pricing_versions.notes IS 'Free text — source/announcement of this pricing.';
COMMENT ON COLUMN model_pricing_versions.created_at IS 'Audit: when this row was first inserted. Auto-stamped by the audit trigger (now() on INSERT); immutable thereafter.';
COMMENT ON COLUMN model_pricing_versions.created_by IS 'Audit: the OWNER — the JWT user (auth.email()) who created this row. Auto-stamped on INSERT; immutable thereafter. NULL for build-time seed rows (no signed-in user).';
COMMENT ON COLUMN model_pricing_versions.modified_at IS 'Audit: when this row was last written. Auto-stamped by the audit trigger (now() on every INSERT/UPDATE).';
COMMENT ON COLUMN model_pricing_versions.modified_by IS 'Audit: the JWT user (auth.email()) who last wrote this row. Auto-stamped on every INSERT/UPDATE.';
COMMENT ON COLUMN model_pricing_versions.modified_by_model IS 'Audit: the AI model credited on the last save when an LLM made/assisted the change (e.g. "gpt-4o"). NULL for plain human writes. Read from the app.modified_by_model session GUC by the audit trigger. The owner (CreatedBy/ModifiedBy) is always the human JWT user, never a model.';

-- ----------------------------------------------------------------------------
-- AssistantTurns: Table: AssistantTurns
-- ----------------------------------------------------------------------------
CREATE TABLE assistant_turns (
  assistant_turn_id                   TEXT                 PRIMARY KEY,         -- Slug/uuid PK for the turn.
  created_at                          TIMESTAMPTZ         ,                     -- When the turn was submitted (ISO timestamp).
  current_state_key                   TEXT                ,                     -- Final state of the chat-agent machine for this turn: 'responding' (success) or 'failed'. Bare StateKey value.
  question_kind                       TEXT                ,                     -- Classifier branch: rulebook / company / claim.
  route_path                          TEXT                ,                     -- Concrete app path the turn was active on, e.g. '/claims/zamora-thiago-2026-01-30'.
  route_key                           TEXT                ,                     -- PlatformNaviation route_key in scope when known (raw string, not an FK — concrete instance paths need not match a nav row).
  citation                            TEXT                ,                     -- FK to the Citation this assistant turn concerns.
  app_user_id                         TEXT                ,                     -- App user who asked (raw id; linked logically).
  ai_model                            TEXT                ,                     -- FK -> AiModels.AiModelId — model that answered.
  model_pricing_version               TEXT                ,                     -- FK -> ModelPricingVersions.ModelPricingVersionId — the exact pricing version used to bill this turn (snapshotted so historical cost is stable even after prices change).
  user_message                        TEXT                ,                     -- The user's question text for this turn.
  assistant_reply                     TEXT                ,                     -- The assistant's reply text.
  raw_exchange                        TEXT                ,                     -- Full request/response metadata as raw JSON (messages, system-prompt kind, usage block, finish reason, latency).
  input_tokens                        INTEGER             ,                     -- Total prompt/input tokens (including any cached).
  cached_input_tokens                 INTEGER             ,                     -- Portion of input tokens served from prompt cache (billed at the cached rate).
  output_tokens                       INTEGER             ,                     -- Completion/output tokens.
  created_by                          TEXT                ,                     -- Audit: the OWNER — the JWT user (auth.email()) who created this row. Auto-stamped on INSERT; immutable thereafter. NULL for build-time seed rows (no signed-in user).
  modified_at                         TIMESTAMPTZ         ,                     -- Audit: when this row was last written. Auto-stamped by the audit trigger (now() on every INSERT/UPDATE).
  modified_by                         TEXT                ,                     -- Audit: the JWT user (auth.email()) who last wrote this row. Auto-stamped on every INSERT/UPDATE.
  modified_by_model                   TEXT                                      -- Audit: the AI model credited on the last save when an LLM made/assisted the change (e.g. "gpt-4o"). NULL for plain human writes. Read from the app.modified_by_model session GUC by the audit trigger. The owner (CreatedBy/ModifiedBy) is always the human JWT user, never a model.
);
COMMENT ON COLUMN assistant_turns.assistant_turn_id IS 'Slug/uuid PK for the turn.';
COMMENT ON COLUMN assistant_turns.created_at IS 'When the turn was submitted (ISO timestamp).';
COMMENT ON COLUMN assistant_turns.current_state_key IS 'Final state of the chat-agent machine for this turn: ''responding'' (success) or ''failed''. Bare StateKey value.';
COMMENT ON COLUMN assistant_turns.question_kind IS 'Classifier branch: rulebook / company / claim.';
COMMENT ON COLUMN assistant_turns.route_path IS 'Concrete app path the turn was active on, e.g. ''/claims/zamora-thiago-2026-01-30''.';
COMMENT ON COLUMN assistant_turns.route_key IS 'PlatformNaviation route_key in scope when known (raw string, not an FK — concrete instance paths need not match a nav row).';
COMMENT ON COLUMN assistant_turns.citation IS 'FK to the Citation this assistant turn concerns.';
COMMENT ON COLUMN assistant_turns.app_user_id IS 'App user who asked (raw id; linked logically).';
COMMENT ON COLUMN assistant_turns.ai_model IS 'FK -> AiModels.AiModelId — model that answered.';
COMMENT ON COLUMN assistant_turns.model_pricing_version IS 'FK -> ModelPricingVersions.ModelPricingVersionId — the exact pricing version used to bill this turn (snapshotted so historical cost is stable even after prices change).';
COMMENT ON COLUMN assistant_turns.user_message IS 'The user''s question text for this turn.';
COMMENT ON COLUMN assistant_turns.assistant_reply IS 'The assistant''s reply text.';
COMMENT ON COLUMN assistant_turns.raw_exchange IS 'Full request/response metadata as raw JSON (messages, system-prompt kind, usage block, finish reason, latency).';
COMMENT ON COLUMN assistant_turns.input_tokens IS 'Total prompt/input tokens (including any cached).';
COMMENT ON COLUMN assistant_turns.cached_input_tokens IS 'Portion of input tokens served from prompt cache (billed at the cached rate).';
COMMENT ON COLUMN assistant_turns.output_tokens IS 'Completion/output tokens.';
COMMENT ON COLUMN assistant_turns.created_by IS 'Audit: the OWNER — the JWT user (auth.email()) who created this row. Auto-stamped on INSERT; immutable thereafter. NULL for build-time seed rows (no signed-in user).';
COMMENT ON COLUMN assistant_turns.modified_at IS 'Audit: when this row was last written. Auto-stamped by the audit trigger (now() on every INSERT/UPDATE).';
COMMENT ON COLUMN assistant_turns.modified_by IS 'Audit: the JWT user (auth.email()) who last wrote this row. Auto-stamped on every INSERT/UPDATE.';
COMMENT ON COLUMN assistant_turns.modified_by_model IS 'Audit: the AI model credited on the last save when an LLM made/assisted the change (e.g. "gpt-4o"). NULL for plain human writes. Read from the app.modified_by_model session GUC by the audit trigger. The owner (CreatedBy/ModifiedBy) is always the human JWT user, never a model.';

