-- ----------------------------------------------------------------------------
-- ERBFeatures: Table: ERBFeatures
-- ----------------------------------------------------------------------------
CREATE TABLE erb_features (
  erb_feature_id                      TEXT                 PRIMARY KEY,         -- PK — kebab logical key for the feature.
  route                               TEXT                ,                     -- Platform route this ERBFeatures row navigates to. Defaults to the "feature-detail" detail route; its template feeds RelativePath.
  erb_package                         TEXT                ,                     -- FK -> ERBPackages.ERBPackageId. The package this feature belongs to (many features -> one package).
  is_licensed                         BOOLEAN             ,                     -- This feature's own licensing flag. When false, the feature is hidden from non-Effortless users regardless of its package (used to fence off Effortless Elements tooling features). Blank/true = licensed.
  title                               TEXT                ,                     -- Human-readable feature name.
  description                         TEXT                ,                     -- What the feature does, in prose.
  category                            TEXT                ,                     -- FK to ERBFeatureCategories — the cross-package functional category this feature belongs to (intake / scoring / module / validation / review / output / extraction / prep / dashboard / integration / data-model / platform / devops).
  status                              TEXT                ,                     -- FK to ERBFeatureStatuses — feature lifecycle status.
  sort_order                          NUMERIC             ,                     -- Display order within the package.
  is_key                              BOOLEAN             ,                     -- Star flag — marks the headline features so users can focus on the top platform capabilities amid the long tail. Blank/false = ordinary features.
  rule_refs                           TEXT                ,                     -- Comma-separated BusinessRules.RuleCode refs (R1..R38) this feature implements, if any.
  source_text                         TEXT                ,                     -- Original / supporting source text (markdown) that describes this feature.
  source_files                        TEXT                ,                     -- Comma-separated repo-relative path(s) of the source document(s).
  image_url                           TEXT                ,                     -- Repo-relative path to a cartoon illustration of this feature (generated, 300x300 PNG under assets/feature-images/).
  created_at                          TIMESTAMPTZ         ,                     -- Audit: when this row was first inserted. Auto-stamped by the audit trigger (now() on INSERT); immutable thereafter.
  created_by                          TEXT                ,                     -- Audit: the OWNER — the JWT user (auth.email()) who created this row. Auto-stamped on INSERT; immutable thereafter. NULL for build-time seed rows (no signed-in user).
  modified_at                         TIMESTAMPTZ         ,                     -- Audit: when this row was last written. Auto-stamped by the audit trigger (now() on every INSERT/UPDATE).
  modified_by                         TEXT                ,                     -- Audit: the JWT user (auth.email()) who last wrote this row. Auto-stamped on every INSERT/UPDATE.
  modified_by_model                   TEXT                                      -- Audit: the AI model credited on the last save when an LLM made/assisted the change (e.g. "gpt-4o"). NULL for plain human writes. Read from the app.modified_by_model session GUC by the audit trigger. The owner (CreatedBy/ModifiedBy) is always the human JWT user, never a model.
);
COMMENT ON COLUMN erb_features.erb_feature_id IS 'PK — kebab logical key for the feature.';
COMMENT ON COLUMN erb_features.route IS 'Platform route this ERBFeatures row navigates to. Defaults to the "feature-detail" detail route; its template feeds RelativePath.';
COMMENT ON COLUMN erb_features.erb_package IS 'FK -> ERBPackages.ERBPackageId. The package this feature belongs to (many features -> one package).';
COMMENT ON COLUMN erb_features.is_licensed IS 'This feature''s own licensing flag. When false, the feature is hidden from non-Effortless users regardless of its package (used to fence off Effortless Elements tooling features). Blank/true = licensed.';
COMMENT ON COLUMN erb_features.title IS 'Human-readable feature name.';
COMMENT ON COLUMN erb_features.description IS 'What the feature does, in prose.';
