-- ----------------------------------------------------------------------------
-- SubjectStateInstances: Table: SubjectStateInstances
-- ----------------------------------------------------------------------------
CREATE TABLE subject_state_instances (
  subject_state_instance_id           TEXT                 PRIMARY KEY,         -- PK: ssi-{subject-table}-{subject-id}-{state-key}-{sequence-index}.
  state_machine                       TEXT                ,                     -- FK -> StateMachines.StateMachineId.
  subject_table_name                  TEXT                ,                     -- Polymorphic table name, e.g. Citations or Hearings.
  subject_id                          TEXT                ,                     -- Polymorphic PK of the subject row.
  state_key                           TEXT                ,                     -- The machine state entered by this occupancy record.
  entered_at                          TIMESTAMPTZ         ,                     -- Timestamp when this state was entered.
  exited_at                           TIMESTAMPTZ         ,                     -- Timestamp when the subject left this state. NULL while current.
  sequence_index                      NUMERIC             ,                     -- 1-based position on this subject's path through the machine.
  prior_instance                      TEXT                ,                     -- Self-FK -> SubjectStateInstances.SubjectStateInstanceId — the previous occupancy in this subject's chain. NULL for the initial state.
  entered_via_transition              TEXT                ,                     -- FK -> StateTransitions.StateTransitionId — the edge event that created this occupancy.
  created_at                          TIMESTAMPTZ         ,                     -- Audit: when this row was first inserted. Auto-stamped by the audit trigger (now() on INSERT); immutable thereafter.
  created_by                          TEXT                ,                     -- Audit: the OWNER — the JWT user (auth.email()) who created this row. Auto-stamped on INSERT; immutable thereafter. NULL for build-time seed rows (no signed-in user).
  modified_at                         TIMESTAMPTZ         ,                     -- Audit: when this row was last written. Auto-stamped by the audit trigger (now() on every INSERT/UPDATE).
  modified_by                         TEXT                ,                     -- Audit: the JWT user (auth.email()) who last wrote this row. Auto-stamped on every INSERT/UPDATE.
  modified_by_model                   TEXT                                      -- Audit: the AI model credited on the last save when an LLM made/assisted the change (e.g. "gpt-4o"). NULL for plain human writes. Read from the app.modified_by_model session GUC by the audit trigger. The owner (CreatedBy/ModifiedBy) is always the human JWT user, never a model.
);
COMMENT ON COLUMN subject_state_instances.subject_state_instance_id IS 'PK: ssi-{subject-table}-{subject-id}-{state-key}-{sequence-index}.';
