COMMENT ON COLUMN subject_state_instances.entered_via_transition IS 'FK -> StateTransitions.StateTransitionId — the edge event that created this occupancy.';
COMMENT ON COLUMN subject_state_instances.created_at IS 'Audit: when this row was first inserted. Auto-stamped by the audit trigger (now() on INSERT); immutable thereafter.';
