RETURNS TEXT AS $$
  SELECT (REPLACE(REPLACE((SELECT NULLIF(route_key, '') FROM platform_naviation WHERE platform_naviation_id = p_platform_naviation_id), '.', ' '), '-', ' '))::text;
$$ LANGUAGE sql STABLE;

