-- calc_state_transition_rules_from_state_key
-- Field: StateTransitionRules.FromStateKey
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: StateKey from related MachineStates


CREATE OR REPLACE FUNCTION calc_state_transition_rules_from_state_key(p_state_transition_rule_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT state_key::text FROM machine_states WHERE machine_state_id = (SELECT from_state FROM state_transition_rules WHERE state_transition_rule_id = p_state_transition_rule_id));
$$ LANGUAGE sql STABLE;

-- calc_state_transition_rules_to_state_key
-- Field: StateTransitionRules.ToStateKey
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: StateKey from related MachineStates


CREATE OR REPLACE FUNCTION calc_state_transition_rules_to_state_key(p_state_transition_rule_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT state_key::text FROM machine_states WHERE machine_state_id = (SELECT to_state FROM state_transition_rules WHERE state_transition_rule_id = p_state_transition_rule_id));
$$ LANGUAGE sql STABLE;

-- calc_state_transition_rules_name
-- Field: StateTransitionRules.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_state_transition_rules_name(p_state_transition_rule_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(state_transition_rule_id, '') FROM state_transition_rules WHERE state_transition_rule_id = p_state_transition_rule_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_state_transition_rules_is_forward_edge
-- Field: StateTransitionRules.IsForwardEdge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_state_transition_rules_is_forward_edge(p_state_transition_rule_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (NOT (calc_state_transition_rules_to_state_key(p_state_transition_rule_id) = 'draft'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_state_transitions_name
-- Field: StateTransitions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_state_transitions_name(p_state_transition_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(state_transition_id, '') FROM state_transitions WHERE state_transition_id = p_state_transition_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_state_transitions_is_forward
-- Field: StateTransitions.IsForward
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_state_transitions_is_forward(p_state_transition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((NOT ((SELECT NULLIF(to_state_key, '') FROM state_transitions WHERE state_transition_id = p_state_transition_id) = 'draft') AND NOT ((SELECT NULLIF(to_state_key, '') FROM state_transitions WHERE state_transition_id = p_state_transition_id) = 'new') AND NOT ((SELECT NULLIF(to_state_key, '') FROM state_transitions WHERE state_transition_id = p_state_transition_id) = 'pending') AND NOT ((SELECT NULLIF(to_state_key, '') FROM state_transitions WHERE state_transition_id = p_state_transition_id) = 'open') AND NOT ((SELECT NULLIF(to_state_key, '') FROM state_transitions WHERE state_transition_id = p_state_transition_id) = 'issued')))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_work_queue_items_name
-- Field: WorkQueueItems.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_work_queue_items_name(p_work_queue_item_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(work_queue_item_id, '') FROM work_queue_items WHERE work_queue_item_id = p_work_queue_item_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_work_queue_items_due_in_days
-- Field: WorkQueueItems.DueInDays
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_work_queue_items_due_in_days(p_work_queue_item_id TEXT)
RETURNS INTEGER AS $$
  SELECT (((SELECT due_date::timestamptz FROM work_queue_items WHERE work_queue_item_id = p_work_queue_item_id)::date - CURRENT_DATE::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_work_queue_items_is_overdue
-- Field: WorkQueueItems.IsOverdue
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_work_queue_items_is_overdue(p_work_queue_item_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_work_queue_items_due_in_days(p_work_queue_item_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN (FALSE)::text ELSE (((SELECT val FROM __erb_dedup_v1))::NUMERIC < 0)::text END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_work_queue_items_urgency_bucket
-- Field: WorkQueueItems.UrgencyBucket
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_work_queue_items_urgency_bucket(p_work_queue_item_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_work_queue_items_due_in_days(p_work_queue_item_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN ('follow-up')::text ELSE (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC <= 0 THEN ('urgent')::text ELSE (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC <= 3 THEN ('due-3-days')::text ELSE ('upcoming')::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_work_queue_items_is_urgent
-- Field: WorkQueueItems.IsUrgent
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_work_queue_items_is_urgent(p_work_queue_item_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_work_queue_items_urgency_bucket(p_work_queue_item_id) = 'urgent')::boolean;
$$ LANGUAGE sql STABLE;

