-- ----------------------------------------------------------------------------
-- vw_business_rules: View for BusinessRules
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_business_rules CASCADE;
CREATE VIEW vw_business_rules WITH (security_invoker = ON) AS
SELECT
  t.business_rule_id,
  calc_business_rules_name(t.business_rule_id) AS name,                         -- Logical key — lowercased rule code.
  t.rule_code,                                                                  -- Stable rule identifier (R1, R2, ... R38).
  t.title,                                                                      -- Short title of the rule.
  t.category,                                                                   -- FK to BusinessRuleCategories — the category bucket this rule belongs to (ROUTING | hard-stop | soft-flag | high-risk | SCORING | DECISION | REVIEW | SUBMISSION | data-integrity).
  t.sort_order,                                                                 -- Display order of the rule within its category (drag/drop sortable).
  t.description,                                                                -- Full rule statement from the platform narrative.
  t.schema_location,                                                            -- Where the rule is enforced in the schema (table.field or formula reference).
  t.created_at,                                                                 -- Audit: when this row was first inserted. Auto-stamped by the audit trigger (now() on INSERT); immutable thereafter.
  t.created_by,                                                                 -- Audit: the OWNER — the JWT user (auth.email()) who created this row. Auto-stamped on INSERT; immutable thereafter. NULL for build-time seed rows (no signed-in user).
  t.modified_at,                                                                -- Audit: when this row was last written. Auto-stamped by the audit trigger (now() on every INSERT/UPDATE).
  t.modified_by,                                                                -- Audit: the JWT user (auth.email()) who last wrote this row. Auto-stamped on every INSERT/UPDATE.
  t.modified_by_model                                                           -- Audit: the AI model credited on the last save when an LLM made/assisted the change (e.g. "gpt-4o"). NULL for plain human writes. Read from the app.modified_by_model session GUC by the audit trigger. The owner (CreatedBy/ModifiedBy) is always the human JWT user, never a model.
FROM business_rules t;

-- ----------------------------------------------------------------------------
-- vw_business_rule_categories: View for BusinessRuleCategories
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_business_rule_categories CASCADE;
CREATE VIEW vw_business_rule_categories WITH (security_invoker = ON) AS
SELECT
  t.business_rule_category_id,                                                  -- PK = slugified category key (routing / hard-stop / soft-flag / high-risk / scoring / decision / review / submission / data-integrity) — matches the slug form BusinessRules.Category links resolve to.
  calc_business_rule_categories_name(t.business_rule_category_id) AS name,      -- Echoes BusinessRuleCategoryId.
  t.title,                                                                      -- Human-readable category title shown on the category card.
  t.description,                                                                -- What this category groups.
  t.sort_order,                                                                 -- Display order of the category card on the Business Rules page (drag/drop sortable).
